// ─────────────────────────────────────────────────────────────
//  AKARI · GLOFOX MEMBER SYNC · CONFIG
//  Once a day: count active Glofox members per Capacity row and update Active Members.
// ─────────────────────────────────────────────────────────────
const cfg = {
  airtableBaseId: 'appXXXXXXXXXXXXXX', // same base as the waitlist workflow
  airtableApi: 'https://api.airtable.com/v0',
  tables: { capacity: 'Capacity', log: 'Activity Log' },

  glofoxApi: 'https://YOUR-GLOFOX-PROXY/prod', // Glofox API base (your proxy), no trailing slash
  // Each branch's members are listed with that branch's ID. A member is counted once, however many branches list them.
  branches: [
    { id: '64c9870292e260894f0247a4', name: 'Williamsburg' },
    { id: '67cf4fe8ef346c3817003b8f', name: 'Greenpoint' },
    { id: '6a1741e58f61326070010c0a', name: 'LES' },
  ],

  countStatuses: ['ACTIVE'], // membership statuses that count as an active member (Jack, 10 Nov: ACTIVE only)
  maxDropShare: 0.5, // a queue whose count falls by more than this share in one day is not written; it is flagged instead
  minRowsForDropCheck: 20, // ...only for queues with at least this many active members today
};

const base = `${cfg.airtableApi}/${cfg.airtableBaseId}`;
cfg.urls = {
  capacity: `${base}/${encodeURIComponent(cfg.tables.capacity)}`,
  log: `${base}/${encodeURIComponent(cfg.tables.log)}`,
};

return [{ json: { cfg } }];

// One item per Glofox branch; the next node pages through that branch's member list.
const { cfg } = $('Config').first().json;
return cfg.branches.map((b) => ({ json: { branch: b.id, name: b.name } }));

// Counts members per Glofox membership name, for the statuses in countStatuses.
// Refuses to continue on an error page or an incomplete list, so a partial read never overwrites Active Members.
const { cfg } = $('Config').first().json;
const statuses = new Set(cfg.countStatuses.map((s) => String(s).toUpperCase()));
const pages = $input.all().map((i) => i.json);

const problems = [];
const seen = new Set();
const perBranch = {}; // branch id → { expected, got }
const counts = {}; // lower-case membership name → { name, n }
for (const p of pages) {
  if (!p || p.success === false || p.message || !Array.isArray(p.data)) {
    problems.push(String((p && (p.message || p.error)) || 'unreadable page').slice(0, 200));
    continue;
  }
  for (const m of p.data) {
    const b = m.branch_id || '?';
    perBranch[b] = perBranch[b] || { expected: Number(p.total_count) || 0, got: 0 };
    perBranch[b].got += 1;
    if (seen.has(m._id)) continue;
    seen.add(m._id);
    const ms = m.membership || {};
    if (!ms.membership_name || !statuses.has(String(ms.status || '').toUpperCase())) continue;
    const key = ms.membership_name.trim().toLowerCase();
    counts[key] = counts[key] || { name: ms.membership_name.trim(), n: 0 };
    counts[key].n += 1;
  }
}
for (const b of cfg.branches) {
  const r = perBranch[b.id];
  if (!r) problems.push(`${b.name}: no members returned`);
  else if (Math.abs(r.got - r.expected) > Math.max(5, r.expected * 0.01)) problems.push(`${b.name}: read ${r.got} of ${r.expected} members`);
}
if (problems.length) throw new Error(`Glofox sync stopped, nothing was changed: ${[...new Set(problems)].join('; ')}`);

return [{ json: { counts, members: seen.size, perBranch } }];

// Works out each Capacity row's Active Members from its "Glofox Memberships" names (one per line)
// and prepares the Airtable updates plus one Activity Log row describing what happened.
const { cfg } = $('Config').first().json;
const { counts, members } = $('Count Members').first().json;
const rows = $('Get Capacity').all().flatMap((i) => i.json.records || []);
const NOW = new Date().toISOString();

const used = new Set();
const updated = [];
const held = [];
const missing = [];
let unchanged = 0;
const writes = [];
for (const r of rows) {
  const names = String(r.fields['Glofox Memberships'] || '').split('\n').map((s) => s.trim()).filter(Boolean);
  if (!names.length) continue;
  const label = r.fields.Queue || `${r.fields.Location} · ${r.fields.Membership}`;
  let n = 0;
  for (const name of names) {
    const key = name.toLowerCase();
    used.add(key);
    if (counts[key]) n += counts[key].n;
    else missing.push(`${label}: "${name}"`);
  }
  const current = Number(r.fields['Active Members'] || 0);
  if (current >= cfg.minRowsForDropCheck && n < current * (1 - cfg.maxDropShare)) {
    held.push(`${label} ${current} → ${n}`);
    continue;
  }
  const fields = { 'Active Counted At': NOW };
  if (n !== current) { fields['Active Members'] = n; updated.push(`${label} ${current} → ${n}`); } else unchanged += 1;
  writes.push({ id: r.id, fields });
}
const notCounted = Object.entries(counts).filter(([k]) => !used.has(k)).sort((a, b) => b[1].n - a[1].n).map(([, v]) => `${v.name} (${v.n})`);

const detail = [
  updated.length ? `Updated: ${updated.join('; ')}` : 'No changes to Active Members.',
  `Unchanged: ${unchanged} queue(s). ${members} Glofox members read.`,
  held.length ? `Held back, count fell by more than ${Math.round(cfg.maxDropShare * 100)}% (check Glofox, then type the number in if it's right): ${held.join('; ')}` : '',
  missing.length ? `Glofox Memberships names not found in Glofox (typo, or nobody active on it): ${missing.join('; ')}` : '',
  notCounted.length ? `Active in Glofox but not counted in any queue: ${notCounted.join(', ')}` : '',
].filter(Boolean).join('\n');

const chunks = [];
for (let i = 0; i < writes.length; i += 10) chunks.push({ records: writes.slice(i, i + 10), typecast: true });
return [{
  json: {
    chunks,
    log: { records: [{ fields: { Summary: `Glofox sync · ${updated.length} queue(s) updated`, Timestamp: NOW, Event: 'Active Synced', Source: 'Glofox', Detail: detail } }], typecast: true },
    updated, held, missing, notCounted,
  },
}];
